def set_path(obj, path, value):
    parts = path.split(".")
    cur = obj
    for p in parts[:-1]:
        cur = cur[int(p) if p.isdigit() else p]
    last = parts[-1]
    cur[int(last) if last.isdigit() else last] = value


def main() -> None:
    data = json.loads(HY.read_text(encoding="utf-8"))
    sec = data["pages"]["security"]
    for path, value in PATCHES.items():
        set_path(sec, path, value)
    data["pages"]["security"] = sec
    HY.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
